};

// Check if query is purely Korean Chosung characters
export function isChosungOnly(query: string): boolean {
  if (!query) return false;
  const cleaned = query.replace(/\s+/g, '');
  return cleaned.split('').every(ch => CHOSUNG_LIST.includes(ch));
}

// Main matching function: matches Korean Title, English Title, Chosung, Acronyms, and Categories
export function matchGameSearch(
  game: { titleKr: string; titleEn: string; categories?: string[]; mechanics?: string[]; publisherKr?: string },
  query: string
): boolean {
  if (!query || !query.trim()) return true;

  const normalizedQuery = query.trim().toLowerCase().replace(/\s+/g, '');
  const krTitleNormalized = game.titleKr.toLowerCase().replace(/\s+/g, '');
  const enTitleNormalized = game.titleEn.toLowerCase().replace(/\s+/g, '');

  // 1. Direct text substring match
  if (krTitleNormalized.includes(normalizedQuery) || enTitleNormalized.includes(normalizedQuery)) {
    return true;
  }

  // 2. Acronym check
  const mappedQuery = KOREAN_ACRONYMS[normalizedQuery];
  if (mappedQuery && (krTitleNormalized.includes(mappedQuery.replace(/\s+/g, '')) || enTitleNormalized.includes(mappedQuery.replace(/\s+/g, '')))) {
    return true;
  }

  // 3. Chosung match
  const krChosung = extractChosung(game.titleKr).replace(/\s+/g, '');
  if (isChosungOnly(query)) {
    if (krChosung.includes(normalizedQuery)) {
      return true;
    }
  }

  // 4. Publisher / Category / Mechanic match
  if (game.publisherKr && game.publisherKr.toLowerCase().replace(/\s+/g, '').includes(normalizedQuery)) {
    return true;
  }
  if (game.categories && game.categories.some(c => c.toLowerCase().replace(/\s+/g, '').includes(normalizedQuery))) {
    return true;
  }
  if (game.mechanics && game.mechanics.some(m => m.toLowerCase().replace(/\s+/g, '').includes(normalizedQuery))) {
    return true;
  }

  return false;
}

import { BoardLifeLinks } from '@/types';

// Generate BoardLife Community & Marketplace deep links for any game
export function getBoardLifeLinks(gameTitleKr: string, gameTitleEn?: string): BoardLifeLinks {
  // Use Korean title first, fallback to English
  const searchTerm = encodeURIComponent(gameTitleKr || gameTitleEn || '');

  return {
    // 1. BoardLife Game Details / Community Search
    infoUrl: `https://boardlife.co.kr/bbs/board.php?bo_table=boardgame_info&sfl=wr_subject&stx=${searchTerm}`,

    // 2. BoardLife Korean Rules & Translation Files / Materials
    rulesUrl: `https://boardlife.co.kr/bbs/board.php?bo_table=rule&sfl=wr_subject&stx=${searchTerm}`,

    // 3. BoardLife Used Marketplace (중고장터 실시간 매물 및 시세 확인)
    usedMarketUrl: `https://boardlife.co.kr/bbs/board.php?bo_table=trade&sfl=wr_subject&stx=${searchTerm}`,

    // 4. BoardLife Strategy / Review Tips (보드게임 공략 & 후기)
    tipsUrl: `https://boardlife.co.kr/bbs/board.php?bo_table=boardgame_tip&sfl=wr_subject&stx=${searchTerm}`,
  };
}

