import { XMLParser } from 'fast-xml-parser';
import { Game, GameStatus } from '@/types';

const BGG_API_BASE = 'https://boardgamegeek.com/xmlapi2';

export interface BGGSearchResult {
  bggId: number;
  titleEn: string;
  yearPublished?: number;
  type: string;
}

export interface BGGGameDetails {
  bggId: number;
  titleEn: string;
  yearPublished?: number;
  image?: string;
  thumbnail?: string;
  minPlayers: number;
  maxPlayers: number;
  bestPlayers?: string;
  minPlaytime: number;
  maxPlaytime: number;
  playingTime: number;
  weight?: number;
  bggRating?: number;
  bggRank?: number;
  categories: string[];
  mechanics: string[];
  designers: string[];
  publishers: string[];
  description?: string;
}

const parser = new XMLParser({
  ignoreAttributes: false,
  attributeNamePrefix: '@_',
  textNodeName: '#text',
  parseAttributeValue: true,
});

export async function searchBGG(query: string, token?: string): Promise<BGGSearchResult[]> {
  try {
    const url = `${BGG_API_BASE}/search?query=${encodeURIComponent(query)}&type=boardgame,boardgameexpansion`;
    const headers: Record<string, string> = {
      'User-Agent': 'BGStatsKorea/1.0',
    };
    if (token) {
      headers['Authorization'] = `Bearer ${token}`;
    }

    const res = await fetch(url, { headers });
    if (!res.ok) {
      console.warn(`BGG search returned status ${res.status}`);
      return [];
    }

    const xml = await res.text();
    const data = parser.parse(xml);

    if (!data.items || !data.items.item) {
      return [];
    }

    const items = Array.isArray(data.items.item) ? data.items.item : [data.items.item];
    return items.map((item: any) => {
      let name = '';
      if (Array.isArray(item.name)) {
        const primary = item.name.find((n: any) => n['@_type'] === 'primary');
        name = primary ? primary['@_value'] : item.name[0]['@_value'];
      } else if (item.name) {
        name = item.name['@_value'];
      }

      return {
        bggId: Number(item['@_id']),
        titleEn: name || 'Unknown Game',
        yearPublished: item.yearpublished ? Number(item.yearpublished['@_value']) : undefined,
        type: item['@_type'] || 'boardgame',
      };
    });
  } catch (error) {
    console.error('Error searching BGG:', error);
    return [];
  }
}

export async function fetchBGGGameDetails(bggId: number, token?: string): Promise<BGGGameDetails | null> {
  try {
    const url = `${BGG_API_BASE}/thing?id=${bggId}&stats=1`;
    const headers: Record<string, string> = {
      'User-Agent': 'BGStatsKorea/1.0',
    };
    if (token) {
      headers['Authorization'] = `Bearer ${token}`;
    }

    const res = await fetch(url, { headers });
    if (!res.ok) return null;

    const xml = await res.text();
    const data = parser.parse(xml);
    if (!data.items || !data.items.item) return null;

    const item = Array.isArray(data.items.item) ? data.items.item[0] : data.items.item;

    // Names
    let titleEn = 'Unknown';
    if (Array.isArray(item.name)) {
      const primary = item.name.find((n: any) => n['@_type'] === 'primary');
      titleEn = primary ? primary['@_value'] : item.name[0]['@_value'];
    } else if (item.name) {
      titleEn = item.name['@_value'];
    }

    // Links (Categories, Mechanics, Designers, Publishers)
    const categories: string[] = [];
    const mechanics: string[] = [];
    const designers: string[] = [];
    const publishers: string[] = [];

    if (item.link) {
      const links = Array.isArray(item.link) ? item.link : [item.link];
      for (const link of links) {
        const type = link['@_type'];
        const val = link['@_value'];
        if (type === 'boardgamecategory') categories.push(val);
        else if (type === 'boardgamemechanic') mechanics.push(val);
        else if (type === 'boardgamedesigner') designers.push(val);
        else if (type === 'boardgamepublisher') publishers.push(val);
      }
    }

    // Stats
    let weight: number | undefined;
    let bggRating: number | undefined;
    let bggRank: number | undefined;

    if (item.statistics && item.statistics.ratings) {
      const ratings = item.statistics.ratings;
      if (ratings.averageweight) weight = parseFloat(Number(ratings.averageweight['@_value']).toFixed(2));
      if (ratings.average) bggRating = parseFloat(Number(ratings.average['@_value']).toFixed(2));

      if (ratings.ranks && ratings.ranks.rank) {
        const ranks = Array.isArray(ratings.ranks.rank) ? ratings.ranks.rank : [ratings.ranks.rank];
        const overallRank = ranks.find((r: any) => r['@_name'] === 'boardgame');
        if (overallRank && overallRank['@_value'] && !isNaN(Number(overallRank['@_value']))) {
          bggRank = Number(overallRank['@_value']);
        }
      }
    }

    // Best player count estimation from poll
    let bestPlayers: string | undefined;
    if (item.poll) {
      const polls = Array.isArray(item.poll) ? item.poll : [item.poll];
      const playerPoll = polls.find((p: any) => p['@_name'] === 'suggested_numplayers');
      if (playerPoll && playerPoll.results) {
        let maxBestVotes = -1;
        let bestNum = '';
        const results = Array.isArray(playerPoll.results) ? playerPoll.results : [playerPoll.results];
        for (const resItem of results) {
          const num = resItem['@_numplayers'];
          if (resItem.result) {
            const votes = Array.isArray(resItem.result) ? resItem.result : [resItem.result];
            const bestVoteObj = votes.find((v: any) => v['@_value'] === 'Best');
            const bestVotes = bestVoteObj ? Number(bestVoteObj['@_numvotes']) || 0 : 0;
            if (bestVotes > maxBestVotes && bestVotes > 0) {
              maxBestVotes = bestVotes;
              bestNum = num;
            }
          }
        }
        if (bestNum) bestPlayers = bestNum;
      }
    }

    return {
      bggId,
      titleEn,
      yearPublished: item.yearpublished ? Number(item.yearpublished['@_value']) : undefined,
      image: item.image || undefined,
      thumbnail: item.thumbnail || undefined,
      minPlayers: item.minplayers ? Number(item.minplayers['@_value']) : 1,
      maxPlayers: item.maxplayers ? Number(item.maxplayers['@_value']) : 4,
      bestPlayers,
      minPlaytime: item.minplaytime ? Number(item.minplaytime['@_value']) : 30,
      maxPlaytime: item.maxplaytime ? Number(item.maxplaytime['@_value']) : 60,
      playingTime: item.playingtime ? Number(item.playingtime['@_value']) : 45,
      weight,
      bggRating,
      bggRank,
      categories,
      mechanics,
      designers,
      publishers,
      description: item.description || '',
    };
  } catch (error) {
    console.error(`Error fetching BGG details for id ${bggId}:`, error);
    return null;
  }
}

export async function fetchBGGUserCollection(username: string, token?: string): Promise<Partial<Game>[]> {
  try {
    const url = `${BGG_API_BASE}/collection?username=${encodeURIComponent(username)}&stats=1`;
    const headers: Record<string, string> = {
      'User-Agent': 'BGStatsKorea/1.0',
    };
    if (token) {
      headers['Authorization'] = `Bearer ${token}`;
    }

    const res = await fetch(url, { headers });
    if (!res.ok) return [];

    const xml = await res.text();
    const data = parser.parse(xml);
    if (!data.items || !data.items.item) return [];

    const items = Array.isArray(data.items.item) ? data.items.item : [data.items.item];

    return items.map((item: any) => {
      let status: GameStatus = 'played';
      if (item.status) {
        if (item.status['@_own'] === 1 || item.status['@_own'] === '1') status = 'owned';
        else if (item.status['@_wishlist'] === 1 || item.status['@_wishlist'] === '1') status = 'wishlist';
        else if (item.status['@_fortrade'] === 1 || item.status['@_fortrade'] === '1') status = 'fortrade';
        else if (item.status['@_preordered'] === 1 || item.status['@_preordered'] === '1') status = 'preordered';
        else if (item.status['@_prevowned'] === 1 || item.status['@_prevowned'] === '1') status = 'prevowned';
      }

      let userRating: number | undefined;
      if (item.stats && item.stats.rating && item.stats.rating['@_value'] !== 'N/A') {
        userRating = Number(item.stats.rating['@_value']) || undefined;
      }

      return {
        bggId: Number(item['@_objectid']),
        titleEn: typeof item.name === 'string' ? item.name : item.name?.['#text'] || 'Unknown',
        titleKr: typeof item.name === 'string' ? item.name : item.name?.['#text'] || 'Unknown',
        yearPublished: item.yearpublished ? Number(item.yearpublished) : undefined,
        image: item.image || undefined,
        thumbnail: item.thumbnail || undefined,
        status,
        userRating,
        minPlayers: item.stats?.['@_minplayers'] ? Number(item.stats['@_minplayers']) : 1,
        maxPlayers: item.stats?.['@_maxplayers'] ? Number(item.stats['@_maxplayers']) : 4,
        minPlaytime: item.stats?.['@_minplaytime'] ? Number(item.stats['@_minplaytime']) : 30,
        maxPlaytime: item.stats?.['@_maxplaytime'] ? Number(item.stats['@_maxplaytime']) : 60,
      };
    });
  } catch (error) {
    console.error('Error fetching BGG user collection:', error);
    return [];
  }
}

import { Game, Play, Player, Location, BGStatsExportRoot, BGStatsExportGame, BGStatsExportPlayer, BGStatsExportLocation, BGStatsExportPlay } from '@/types';

// Convert BG Stats JSON backup to our App database objects
export function parseBGStatsJson(jsonData: any): {
  games: Game[];
  players: Player[];
  locations: Location[];
  plays: Play[];
} {
  const games: Game[] = [];
  const players: Player[] = [];
  const locations: Location[] = [];
  const plays: Play[] = [];

  // Mapping from BG Stats integer IDs to UUIDs
  const gameIdMap = new Map<number, string>();
  const playerIdMap = new Map<number, string>();
  const locationIdMap = new Map<number, string>();

  // 1. Parse Players
  if (Array.isArray(jsonData.players)) {
    jsonData.players.forEach((p: BGStatsExportPlayer) => {
      const id = p.uuid || `player-${p.id}`;
      gameIdMap.set(p.id, id);
      playerIdMap.set(p.id, id);

      const isUser = jsonData.userInfo?.mePlayerRefId === p.id;

      players.push({
        id,
        name: p.name || '알 수 없는 플레이어',
        isUser,
        bggUsername: p.bggUsername || undefined,
        avatar: isUser ? '👑' : '🎲',
        createdAt: p.modificationDate || new Date().toISOString(),
        updatedAt: p.modificationDate || new Date().toISOString(),
      });
    });
  }

  // 2. Parse Locations
  if (Array.isArray(jsonData.locations)) {
    jsonData.locations.forEach((loc: BGStatsExportLocation) => {
      const id = loc.uuid || `loc-${loc.id}`;
      locationIdMap.set(loc.id, id);

      locations.push({
        id,
        name: loc.name || '알 수 없는 장소',
        createdAt: loc.modificationDate || new Date().toISOString(),
      });
    });
  }

  // 3. Parse Games
  if (Array.isArray(jsonData.games)) {
    jsonData.games.forEach((g: BGStatsExportGame) => {
      const id = g.uuid || `game-${g.id}`;
      gameIdMap.set(g.id, id);

      // Check purchase price from copies if present
      let purchasePrice: number | undefined;
      if (g.copies && g.copies.length > 0 && g.copies[0].pricePaid) {
        const parsed = parseFloat(g.copies[0].pricePaid);
        if (!isNaN(parsed)) purchasePrice = parsed;
      }

      games.push({
        id,
        bggId: g.bggId ? Number(g.bggId) : undefined,
        titleKr: g.name || '제목 없음',
        titleEn: g.name || 'Untitled',
        image: g.image || undefined,
        thumbnail: g.thumbnail || undefined,
        minPlayers: g.minPlayers || 1,
        maxPlayers: g.maxPlayers || 4,
        minPlaytime: g.minPlayTime || 30,
        maxPlaytime: g.maxPlayTime || 60,
        status: 'owned',
        userRating: g.rating ? Number(g.rating) : undefined,
        purchasePrice,
        isExpansion: g.isExpansion === 1,
        createdAt: g.modificationDate || new Date().toISOString(),
        updatedAt: g.modificationDate || new Date().toISOString(),
      });
    });
  }

  // 4. Parse Plays
  if (Array.isArray(jsonData.plays)) {
    jsonData.plays.forEach((play: BGStatsExportPlay) => {
      const id = play.uuid || `play-${play.id}`;
      const gameUuid = gameIdMap.get(play.gameRefId);
      if (!gameUuid) return; // Skip orphaned plays

      const matchingGame = games.find(g => g.id === gameUuid);
      const locUuid = play.locationRefId ? locationIdMap.get(play.locationRefId) : undefined;
      const matchingLoc = locations.find(l => l.id === locUuid);

      const playerScores = (play.playerScores || []).map((ps) => {
        const playerUuid = playerIdMap.get(ps.playerRefId) || `player-${ps.playerRefId}`;
        const scoreNum = ps.score ? parseFloat(ps.score) : undefined;
        return {
          playerId: playerUuid,
          role: ps.role || undefined,
          startPlayer: Boolean(ps.startPlayer),
          score: isNaN(Number(scoreNum)) ? undefined : scoreNum,
          rank: ps.rank ? Number(ps.rank) : undefined,
          winner: Boolean(ps.winner),
          newPlayer: Boolean(ps.newPlayer),
        };
      });

      // Cooperative play check
      const isCoop = play.scoringSetting === 2; // In BG Stats, 2 often denotes coop
      const coopWon = isCoop ? play.nemesisWon === 0 : undefined;

      plays.push({
        id,
        bggPlayId: play.bggId ? Number(play.bggId) : undefined,
        gameId: gameUuid,
        gameTitleKr: matchingGame?.titleKr || '게임',
        gameTitleEn: matchingGame?.titleEn || 'Game',
        gameImage: matchingGame?.thumbnail || matchingGame?.image,
        date: play.playDate ? play.playDate.substring(0, 10) : new Date().toISOString().substring(0, 10),
        durationMinutes: play.durationMin || 45,
        locationId: locUuid,
        locationName: matchingLoc?.name,
        isCoop,
        coopWon,
        isSolo: playerScores.length === 1,
        playerScores,
        notes: play.comments || undefined,
        rating: play.rating ? Number(play.rating) : undefined,
        syncedToBgg: Boolean(play.bggId),
        createdAt: play.modificationDate || new Date().toISOString(),
        updatedAt: play.modificationDate || new Date().toISOString(),
      });
    });
  }

  return { games, players, locations, plays };
}

// Export our App database objects to standard BG Stats JSON format
export function exportToBGStatsJson(
  games: Game[],
  players: Player[],
  locations: Location[],
  plays: Play[]
): BGStatsExportRoot {
  // Build reverse sequential IDs
  const gameToIdMap = new Map<string, number>();
  const playerToIdMap = new Map<string, number>();
  const locationToIdMap = new Map<string, number>();

  const exportGames: BGStatsExportGame[] = games.map((g, idx) => {
    const intId = idx + 1;
    gameToIdMap.set(g.id, intId);
    return {
      id: intId,
      uuid: g.id,
      bggId: g.bggId,
      name: g.titleKr || g.titleEn,
      image: g.image,
      thumbnail: g.thumbnail,
      minPlayers: g.minPlayers,
      maxPlayers: g.maxPlayers,
      minPlayTime: g.minPlaytime,
      maxPlayTime: g.maxPlaytime,
      isExpansion: g.isExpansion ? 1 : 0,
      rating: g.userRating,
      copies: g.purchasePrice ? [{ pricePaid: String(g.purchasePrice), currency: 'KRW' }] : undefined,
      modificationDate: g.updatedAt || new Date().toISOString(),
    };
  });

  let meRefId: number | undefined;
  const exportPlayers: BGStatsExportPlayer[] = players.map((p, idx) => {
    const intId = idx + 1;
    playerToIdMap.set(p.id, intId);
    if (p.isUser) meRefId = intId;
    return {
      id: intId,
      uuid: p.id,
      name: p.name,
      bggUsername: p.bggUsername,
      modificationDate: p.updatedAt || new Date().toISOString(),
    };
  });

  const exportLocations: BGStatsExportLocation[] = locations.map((l, idx) => {
    const intId = idx + 1;
    locationToIdMap.set(l.id, intId);
    return {
      id: intId,
      uuid: l.id,
      name: l.name,
      modificationDate: l.createdAt || new Date().toISOString(),
    };
  });

  const exportPlays: BGStatsExportPlay[] = plays.map((play, idx) => {
    const intId = idx + 1;
    const gameRefId = gameToIdMap.get(play.gameId) || 1;
    const locationRefId = play.locationId ? locationToIdMap.get(play.locationId) : undefined;

    const playerScores = play.playerScores.map(ps => ({
      playerRefId: playerToIdMap.get(ps.playerId) || 1,
      score: ps.score !== undefined ? String(ps.score) : undefined,
      winner: ps.winner ? 1 : 0,
      startPlayer: ps.startPlayer ? 1 : 0,
      newPlayer: ps.newPlayer ? 1 : 0,
      role: ps.role,
      rank: ps.rank,
    }));

    return {
      id: intId,
      uuid: play.id,
      gameRefId,
      playDate: play.date + ' 12:00:00',
      durationMin: play.durationMinutes,
      locationRefId,
      scoringSetting: play.isCoop ? 2 : 0,
      nemesisWon: play.isCoop && !play.coopWon ? 1 : 0,
      playerScores,
      comments: play.notes,
      rating: play.rating,
      bggId: play.bggPlayId,
      modificationDate: play.updatedAt || new Date().toISOString(),
    };
  });

  return {
    games: exportGames,
    players: exportPlayers,
    locations: exportLocations,
    plays: exportPlays,
    userInfo: meRefId ? { mePlayerRefId: meRefId } : undefined,
  };
}

import { Game, Play, Player } from '@/types';

// Calculate H-Index given an array of play counts
export function calculateHIndex(playCounts: number[]): number {
  if (!playCounts || playCounts.length === 0) return 0;
  const sorted = [...playCounts].sort((a, b) => b - a);
  let h = 0;
  for (let i = 0; i < sorted.length; i++) {
    if (sorted[i] >= i + 1) {
      h = i + 1;
    } else {
      break;
    }
  }
  return h;
}

export interface GamePlayStats {
  gameId: string;
  gameTitleKr: string;
  gameTitleEn: string;
  thumbnail?: string;
  playCount: number;
  totalDurationMinutes: number;
  userPlays: number;
  userWins: number;
  userWinRate: number;
  highScore?: number;
  averageScore?: number;
  lastPlayedDate?: string;
  costPerPlay?: number;
  purchasePrice?: number;
}

// Calculate play statistics per game
export function calculateGameStatsMap(games: Game[], plays: Play[], currentUserId: string = 'player-me'): Map<string, GamePlayStats> {
  const map = new Map<string, GamePlayStats>();

  games.forEach(g => {
    map.set(g.id, {
      gameId: g.id,
      gameTitleKr: g.titleKr,
      gameTitleEn: g.titleEn,
      thumbnail: g.thumbnail || g.image,
      playCount: 0,
      totalDurationMinutes: 0,
      userPlays: 0,
      userWins: 0,
      userWinRate: 0,
      purchasePrice: g.purchasePrice,
      costPerPlay: g.purchasePrice,
    });
  });

  const scoresByGame = new Map<string, number[]>();

  plays.forEach(play => {
    let stat = map.get(play.gameId);
    if (!stat) {
      stat = {
        gameId: play.gameId,
        gameTitleKr: play.gameTitleKr || '알 수 없는 게임',
        gameTitleEn: play.gameTitleEn || 'Unknown Game',
        thumbnail: play.gameImage,
        playCount: 0,
        totalDurationMinutes: 0,
        userPlays: 0,
        userWins: 0,
        userWinRate: 0,
      };
      map.set(play.gameId, stat);
    }

    stat.playCount += 1;
    stat.totalDurationMinutes += play.durationMinutes || 0;
    if (!stat.lastPlayedDate || play.date > stat.lastPlayedDate) {
      stat.lastPlayedDate = play.date;
    }

    // Check current user participation and scores
    const userScore = play.playerScores.find(ps => ps.playerId === currentUserId);
    if (userScore) {
      stat.userPlays += 1;
      if (userScore.winner || (play.isCoop && play.coopWon)) {
        stat.userWins += 1;
      }
      if (userScore.score !== undefined) {
        if (!scoresByGame.has(play.gameId)) scoresByGame.set(play.gameId, []);
        scoresByGame.get(play.gameId)!.push(userScore.score);
      }
    }
  });

  // Post process averages & cost per play
  map.forEach((stat, gameId) => {
    if (stat.userPlays > 0) {
      stat.userWinRate = Math.round((stat.userWins / stat.userPlays) * 100);
    }
    const scores = scoresByGame.get(gameId);
    if (scores && scores.length > 0) {
      stat.highScore = Math.max(...scores);
      stat.averageScore = Math.round(scores.reduce((a, b) => a + b, 0) / scores.length);
    }
    if (stat.purchasePrice && stat.playCount > 0) {
      stat.costPerPlay = Math.round(stat.purchasePrice / stat.playCount);
    }
  });

  return map;
}

export interface PlayerStats {
  player: Player;
  totalPlays: number;
  totalWins: number;
  winRate: number;
  headToHeadWithUser?: {
    totalSharedPlays: number;
    userWins: number;
    playerWins: number;
    userWinRateAgainst: number;
  };
}

// Calculate individual and head-to-head player stats
export function calculateAllPlayerStats(players: Player[], plays: Play[], currentUserId: string = 'player-me'): PlayerStats[] {
  return players.map(player => {
    let totalPlays = 0;
    let totalWins = 0;
    let sharedPlays = 0;
    let userWinsInShared = 0;
    let playerWinsInShared = 0;

    plays.forEach(play => {
      const ps = play.playerScores.find(p => p.playerId === player.id);
      const userPs = play.playerScores.find(p => p.playerId === currentUserId);

      if (ps) {
        totalPlays += 1;
        if (ps.winner || (play.isCoop && play.coopWon)) {
          totalWins += 1;
        }

        if (userPs && player.id !== currentUserId) {
          sharedPlays += 1;
          if (userPs.winner) userWinsInShared += 1;
          if (ps.winner) playerWinsInShared += 1;
        }
      }
    });

    const winRate = totalPlays > 0 ? Math.round((totalWins / totalPlays) * 100) : 0;
    const userWinRateAgainst = sharedPlays > 0 ? Math.round((userWinsInShared / sharedPlays) * 100) : 0;

    return {
      player,
      totalPlays,
      totalWins,
      winRate,
      headToHeadWithUser: player.id !== currentUserId ? {
        totalSharedPlays: sharedPlays,
        userWins: userWinsInShared,
        playerWins: playerWinsInShared,
        userWinRateAgainst,
      } : undefined,
    };
  });
}

// Calculate First Player Advantage in competitive plays
export function calculateFirstPlayerAdvantage(plays: Play[]): {
  firstPlayerPlays: number;
  firstPlayerWins: number;
  firstPlayerWinRate: number;
  nonFirstPlayerWinRate: number;
} {
  let firstPlayerPlays = 0;
  let firstPlayerWins = 0;
  let totalCompetitivePlays = 0;

  plays.forEach(play => {
    if (play.isCoop || play.isSolo || play.playerScores.length < 2) return;

    const startP = play.playerScores.find(ps => ps.startPlayer);
    if (startP) {
      firstPlayerPlays += 1;
      totalCompetitivePlays += 1;
      if (startP.winner) {
        firstPlayerWins += 1;
      }
    }
  });

  const firstPlayerWinRate = firstPlayerPlays > 0 ? Math.round((firstPlayerWins / firstPlayerPlays) * 100) : 0;
  const nonFirstPlayerWinRate = firstPlayerPlays > 0 ? 100 - firstPlayerWinRate : 0;

  return {
    firstPlayerPlays,
    firstPlayerWins,
    firstPlayerWinRate,
    nonFirstPlayerWinRate,
  };
}

// Generate 365 days Activity Grass Data for the given year
export function generateActivityHeatmap(plays: Play[], year: number = new Date().getFullYear()): { date: string; count: number; level: number }[] {
  const countsByDate = new Map<string, number>();

  plays.forEach(play => {
    if (play.date && play.date.startsWith(String(year))) {
      countsByDate.set(play.date, (countsByDate.get(play.date) || 0) + 1);
    }
  });

  const result: { date: string; count: number; level: number }[] = [];
  const start = new Date(year, 0, 1);
  const end = new Date(year, 11, 31);

  for (let d = new Date(start); d <= end; d.setDate(d.getDate() + 1)) {
    const dateStr = d.toISOString().substring(0, 10);
    const count = countsByDate.get(dateStr) || 0;
    let level = 0;
    if (count === 1) level = 1;
    else if (count === 2) level = 2;
    else if (count >= 3 && count < 5) level = 3;
    else if (count >= 5) level = 4;

    result.push({ date: dateStr, count, level });
  }

  return result;
}

// Aggregate Mechanics and Categories play frequency
export function calculateMechanismsAndCategories(games: Game[], plays: Play[]): {
  topMechanics: { name: string; count: number }[];
  topCategories: { name: string; count: number }[];
} {
  const gameMap = new Map<string, Game>();
  games.forEach(g => gameMap.set(g.id, g));

  const mechanicCounts = new Map<string, number>();
  const categoryCounts = new Map<string, number>();

  plays.forEach(play => {
    const game = gameMap.get(play.gameId);
    if (!game) return;

    (game.mechanics || []).forEach(m => {
      mechanicCounts.set(m, (mechanicCounts.get(m) || 0) + 1);
    });
    (game.categories || []).forEach(c => {
      categoryCounts.set(c, (categoryCounts.get(c) || 0) + 1);
    });
  });

  const topMechanics = Array.from(mechanicCounts.entries())
    .map(([name, count]) => ({ name, count }))
    .sort((a, b) => b.count - a.count)
    .slice(0, 8);

  const topCategories = Array.from(categoryCounts.entries())
    .map(([name, count]) => ({ name, count }))
    .sort((a, b) => b.count - a.count)
    .slice(0, 8);

  return { topMechanics, topCategories };
}

import { NextRequest, NextResponse } from 'next/server';
import { searchBGG } from '@/lib/bgg-client';

export async function GET(request: NextRequest) {
  const { searchParams } = new URL(request.url);
  const query = searchParams.get('query');
  const token = searchParams.get('token') || undefined;

  if (!query) {
    return NextResponse.json({ error: 'Query parameter is required' }, { status: 400 });
  }

  try {
    const results = await searchBGG(query, token);
    return NextResponse.json({ results });
  } catch (error: any) {
    return NextResponse.json({ error: error.message || 'Failed to search BGG' }, { status: 500 });
  }
}

import { NextRequest, NextResponse } from 'next/server';
import { fetchBGGGameDetails } from '@/lib/bgg-client';

export async function GET(request: NextRequest) {
  const { searchParams } = new URL(request.url);
  const idStr = searchParams.get('id');
  const token = searchParams.get('token') || undefined;

  if (!idStr || isNaN(Number(idStr))) {
    return NextResponse.json({ error: 'Valid BGG ID is required' }, { status: 400 });
  }

  try {
    const details = await fetchBGGGameDetails(Number(idStr), token);
    if (!details) {
      return NextResponse.json({ error: 'Game not found on BGG' }, { status: 404 });
    }
    return NextResponse.json({ game: details });
  } catch (error: any) {
    return NextResponse.json({ error: error.message || 'Failed to fetch BGG details' }, { status: 500 });
  }
}

import { NextRequest, NextResponse } from 'next/server';
import { fetchBGGUserCollection } from '@/lib/bgg-client';

export async function GET(request: NextRequest) {
  const { searchParams } = new URL(request.url);
  const username = searchParams.get('username');
  const token = searchParams.get('token') || undefined;

  if (!username) {
    return NextResponse.json({ error: 'Username is required' }, { status: 400 });
  }

  try {
    const items = await fetchBGGUserCollection(username, token);
    return NextResponse.json({ items });
  } catch (error: any) {
    return NextResponse.json({ error: error.message || 'Failed to fetch BGG collection' }, { status: 500 });
  }
}

