  const [userRating, setUserRating] = useState<number | undefined>(game?.userRating);
  const [purchasePrice, setPurchasePrice] = useState<number | undefined>(game?.purchasePrice);
  const [organizer, setOrganizer] = useState<string>(game?.organizer || '');
  const [notes, setNotes] = useState<string>(game?.notes || '');
  const [sleeves, setSleeves] = useState(game?.sleeves || []);

  if (!isOpen || !game) return null;

  const blLinks = getBoardLifeLinks(game.titleKr, game.titleEn);
  const gameStatsMap = calculateGameStatsMap([game], plays);
  const stats = gameStatsMap.get(game.id);

  const handleSaveEdit = async () => {
    await db.games.update(game.id, {
      status,
      userRating,
      purchasePrice,
      organizer,
      notes,
      sleeves,
      updatedAt: new Date().toISOString(),
    });
    setIsEditing(false);
