'use client';

import React from 'react';
import { 
  Dices, 
  Clock, 
  Library, 
  Trophy, 
  Flame, 
  TrendingUp, 
  Award,
  Crown
} from 'lucide-react';
import { Game, Play, Player } from '@/types';
import { calculateHIndex, calculateGameStatsMap } from '@/lib/stats-calculator';

interface OverviewStatsProps {
  games: Game[];
  plays: Play[];
  players: Player[];
  currentUserId?: string;
}

export const OverviewStats: React.FC<OverviewStatsProps> = ({
  games,
  plays,
  players,
  currentUserId = 'player-me',
}) => {
  const totalPlays = plays.length;
  const totalMinutes = plays.reduce((acc, p) => acc + (p.durationMinutes || 0), 0);
  const totalHours = Math.round(totalMinutes / 60);

  const ownedGamesCount = games.filter(g => g.status === 'owned').length;

  // User win rate
  let userPlaysCount = 0;
  let userWinsCount = 0;
  plays.forEach(play => {
    const ps = play.playerScores.find(p => p.playerId === currentUserId);
    if (ps) {
      userPlaysCount += 1;
      if (ps.winner || (play.isCoop && play.coopWon)) {
        userWinsCount += 1;
      }
    }
  });
  const userWinRate = userPlaysCount > 0 ? Math.round((userWinsCount / userPlaysCount) * 100) : 0;

  // H-Index Calculation
  const gameStats = calculateGameStatsMap(games, plays, currentUserId);
  const playCounts = Array.from(gameStats.values()).map(s => s.playCount);
  const hIndex = calculateHIndex(playCounts);

  // Most played game
  let mostPlayedGameTitle = '-';
  let mostPlayedCount = 0;
  gameStats.forEach((stat) => {
    if (stat.playCount > mostPlayedCount) {
      mostPlayedCount = stat.playCount;
      mostPlayedGameTitle = stat.gameTitleKr;
    }
  });

  return (
    <div className="grid grid-cols-2 sm:grid-cols-3 lg:grid-cols-6 gap-3">
      {/* 1. Total Plays */}
      <div className="p-4 rounded-2xl bg-gradient-to-br from-indigo-950/60 to-slate-900 border border-indigo-500/30 shadow-lg">
        <div className="flex items-center justify-between text-indigo-400 mb-2">
          <span className="text-xs font-bold uppercase tracking-wider">총 플레이</span>
          <Dices className="w-4 h-4" />
        </div>
        <div className="text-2xl font-black text-white">{totalPlays}</div>
        <p className="text-[11px] text-slate-400 mt-1">총 세션 기록</p>
      </div>

      {/* 2. Total Playtime */}
      <div className="p-4 rounded-2xl bg-gradient-to-br from-sky-950/60 to-slate-900 border border-sky-500/30 shadow-lg">
        <div className="flex items-center justify-between text-sky-400 mb-2">
          <span className="text-xs font-bold uppercase tracking-wider">총 플레이 시간</span>
          <Clock className="w-4 h-4" />
        </div>
        <div className="text-2xl font-black text-white">{totalHours}<span className="text-sm font-normal text-slate-400 ml-1">시간</span></div>
        <p className="text-[11px] text-slate-400 mt-1">{totalMinutes.toLocaleString()}분 플레이</p>
      </div>

      {/* 3. Owned Games */}
      <div className="p-4 rounded-2xl bg-gradient-to-br from-emerald-950/60 to-slate-900 border border-emerald-500/30 shadow-lg">
        <div className="flex items-center justify-between text-emerald-400 mb-2">
          <span className="text-xs font-bold uppercase tracking-wider">보유 게임</span>
          <Library className="w-4 h-4" />
        </div>
        <div className="text-2xl font-black text-white">{ownedGamesCount}<span className="text-sm font-normal text-slate-400 ml-1">개</span></div>
        <p className="text-[11px] text-slate-400 mt-1">전체 등록: {games.length}개</p>
      </div>

      {/* 4. Win Rate */}
      <div className="p-4 rounded-2xl bg-gradient-to-br from-amber-950/60 to-slate-900 border border-amber-500/30 shadow-lg">
        <div className="flex items-center justify-between text-amber-400 mb-2">
          <span className="text-xs font-bold uppercase tracking-wider">나의 승률</span>
          <Trophy className="w-4 h-4" />
        </div>
        <div className="text-2xl font-black text-amber-300">{userWinRate}%</div>
        <p className="text-[11px] text-slate-400 mt-1">{userPlaysCount}전 {userWinsCount}승</p>
      </div>

      {/* 5. H-Index */}
      <div className="p-4 rounded-2xl bg-gradient-to-br from-purple-950/60 to-slate-900 border border-purple-500/30 shadow-lg">
        <div className="flex items-center justify-between text-purple-400 mb-2">
          <span className="text-xs font-bold uppercase tracking-wider">H-Index</span>
          <Award className="w-4 h-4" />
        </div>
        <div className="text-2xl font-black text-purple-300">H - {hIndex}</div>
        <p className="text-[11px] text-slate-400 mt-1">{hIndex}개 게임을 {hIndex}회 이상 플레이</p>
      </div>

      {/* 6. Most Played Game */}
      <div className="p-4 rounded-2xl bg-gradient-to-br from-rose-950/60 to-slate-900 border border-rose-500/30 shadow-lg">
        <div className="flex items-center justify-between text-rose-400 mb-2">
          <span className="text-xs font-bold uppercase tracking-wider">최애 게임</span>
          <Crown className="w-4 h-4" />
        </div>
        <div className="text-base font-black text-white truncate leading-snug">{mostPlayedGameTitle}</div>
        <p className="text-[11px] text-slate-400 mt-1">총 {mostPlayedCount}회 플레이</p>
      </div>
    </div>
  );
};

'use client';

import React, { useMemo } from 'react';
import { Play } from '@/types';
import { generateActivityHeatmap } from '@/lib/stats-calculator';
import { Calendar, Flame } from 'lucide-react';

interface ActivityHeatmapProps {
  plays: Play[];
  year?: number;
}

export const ActivityHeatmap: React.FC<ActivityHeatmapProps> = ({
  plays,
  year = new Date().getFullYear(),
}) => {
  const daysData = useMemo(() => generateActivityHeatmap(plays, year), [plays, year]);

  const totalDaysWithPlays = daysData.filter(d => d.count > 0).length;
  const totalYearPlays = daysData.reduce((acc, d) => acc + d.count, 0);

  // Group days into 53 weeks (columns) x 7 days (rows)
  const weeks = useMemo(() => {
    const cols: typeof daysData[] = [];
    let currentWeek: typeof daysData = [];

    daysData.forEach((day, index) => {
      currentWeek.push(day);
      if (currentWeek.length === 7 || index === daysData.length - 1) {
        cols.push(currentWeek);
        currentWeek = [];
      }
    });

    return cols;
  }, [daysData]);

  // Color mapping based on play count
  const getCellColor = (level: number) => {
    switch (level) {
      case 1: return 'bg-indigo-900/80 border-indigo-700/60';
      case 2: return 'bg-indigo-600 border-indigo-500';
      case 3: return 'bg-indigo-400 border-indigo-300';
      case 4: return 'bg-emerald-400 border-emerald-300 shadow-sm shadow-emerald-400/30';
      default: return 'bg-slate-800/60 border-slate-800';
    }
  };

  return (
    <div className="p-5 rounded-2xl bg-slate-900/90 border border-slate-800 space-y-4">
      {/* Header */}
      <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-2">
        <div className="flex items-center gap-2">
          <div className="p-1.5 rounded-lg bg-indigo-500/20 text-indigo-400 border border-indigo-500/30">
            <Flame className="w-4 h-4" />
          </div>
          <div>
            <h4 className="font-bold text-sm text-white">{year}년 보드게임 라이프 잔디 (Activity Heatmap)</h4>
            <p className="text-xs text-slate-400">총 <strong>{totalDaysWithPlays}일</strong> 동안 <strong>{totalYearPlays}회</strong> 플레이</p>
          </div>
        </div>

        {/* Legend */}
        <div className="flex items-center gap-1.5 text-[11px] text-slate-400">
          <span>적음</span>
          <div className="w-2.5 h-2.5 rounded-sm bg-slate-800/60 border border-slate-800"></div>
          <div className="w-2.5 h-2.5 rounded-sm bg-indigo-900/80 border border-indigo-700/60"></div>
          <div className="w-2.5 h-2.5 rounded-sm bg-indigo-600 border border-indigo-500"></div>
          <div className="w-2.5 h-2.5 rounded-sm bg-indigo-400 border border-indigo-300"></div>
          <div className="w-2.5 h-2.5 rounded-sm bg-emerald-400 border border-emerald-300"></div>
          <span>많음</span>
        </div>
      </div>

      {/* Heatmap Grid */}
      <div className="overflow-x-auto pb-2">
        <div className="flex gap-1 min-w-[700px]">
          {weeks.map((week, wIdx) => (
            <div key={wIdx} className="flex flex-col gap-1">
              {week.map((day) => (
                <div
                  key={day.date}
                  className={`w-3 h-3 rounded-sm border transition-transform hover:scale-125 cursor-pointer ${getCellColor(day.level)}`}
                  title={`${day.date}: ${day.count}회 플레이`}
                />
              ))}
            </div>
          ))}
        </div>
      </div>
    </div>
  );
};

'use client';

import React from 'react';
import { Trophy, CheckCircle2, Target, Plus, Flame } from 'lucide-react';
import { Challenge, Game, Play } from '@/types';
import { calculateGameStatsMap } from '@/lib/stats-calculator';

interface ChallengeTrackerProps {
  challenge: Challenge;
  games: Game[];
  plays: Play[];
}

export const ChallengeTracker: React.FC<ChallengeTrackerProps> = ({
  challenge,
  games,
  plays,
}) => {
  const gameStats = calculateGameStatsMap(games, plays);
  const targetPlays = challenge.targetPlaysPerGame || 10;

  // Selected games in challenge
  const challengeGames = challenge.gameIds.map(id => {
    const game = games.find(g => g.id === id);
    const stats = gameStats.get(id);
    const playCount = stats?.playCount || 0;
    const progress = Math.min(100, Math.round((playCount / targetPlays) * 100));
    const isCompleted = playCount >= targetPlays;

    return {
      id,
      titleKr: game?.titleKr || '알 수 없는 게임',
      titleEn: game?.titleEn || 'Unknown',
      thumbnail: game?.thumbnail || game?.image,
      playCount,
      progress,
      isCompleted,
    };
  });

  const totalPossiblePlays = challenge.gameIds.length * targetPlays;
  const currentTotalPlays = challengeGames.reduce((acc, g) => acc + Math.min(targetPlays, g.playCount), 0);
  const overallProgress = totalPossiblePlays > 0 ? Math.round((currentTotalPlays / totalPossiblePlays) * 100) : 0;
  const completedGamesCount = challengeGames.filter(g => g.isCompleted).length;

  return (
    <div className="p-5 rounded-2xl bg-slate-900/90 border border-slate-800 space-y-4">
      {/* Header & Overall Progress */}
      <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-3">
        <div className="flex items-center gap-2.5">
          <div className="p-2 rounded-xl bg-purple-500/20 text-purple-400 border border-purple-500/30">
            <Target className="w-5 h-5" />
          </div>
          <div>
            <h4 className="font-bold text-base text-white flex items-center gap-2">
              {challenge.title}
              <span className="text-xs px-2 py-0.5 rounded-full bg-purple-500/20 text-purple-300 font-bold border border-purple-500/30">
                {challenge.type}
              </span>
            </h4>
            <p className="text-xs text-slate-400">
              {challengeGames.length}개 게임 각 {targetPlays}회 플레이 도전
            </p>
          </div>
        </div>

        {/* Big Overall Metric */}
        <div className="flex items-center gap-3">
          <div className="text-right">
            <span className="text-xs text-slate-400 font-medium">전체 달성률</span>
            <div className="text-lg font-black text-purple-300">{overallProgress}% ({completedGamesCount}/{challengeGames.length}개 완료)</div>
          </div>
        </div>
      </div>

      {/* Main Progress Bar */}
      <div className="w-full h-2.5 bg-slate-800 rounded-full overflow-hidden">
        <div 
          className="h-full bg-gradient-to-r from-purple-600 via-indigo-500 to-sky-400 transition-all duration-500 rounded-full"
          style={{ width: `${overallProgress}%` }}
        />
      </div>

      {/* Grid of Games in Challenge */}
      <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-5 gap-2.5 pt-2">
        {challengeGames.map((g) => (
          <div
            key={g.id}
            className={`p-3 rounded-xl border transition-all flex flex-col justify-between ${
              g.isCompleted
                ? 'bg-emerald-950/20 border-emerald-500/40 text-emerald-200'
                : 'bg-slate-800/60 border-slate-700/60 text-slate-300'
            }`}
          >
            <div className="flex items-center gap-2.5 mb-2">
              {g.thumbnail ? (
                <img src={g.thumbnail} alt="" className="w-8 h-8 rounded-lg object-cover flex-shrink-0" />
              ) : (
                <div className="w-8 h-8 rounded-lg bg-slate-700 flex items-center justify-center text-xs flex-shrink-0">🎲</div>
              )}
              <div className="min-w-0 flex-1">
                <h5 className="text-xs font-bold truncate text-white leading-tight">{g.titleKr}</h5>
                <span className="text-[10px] text-slate-400 block truncate">{g.titleEn}</span>
              </div>
            </div>

            <div className="space-y-1">
              <div className="flex items-center justify-between text-[11px]">
                <span className="font-bold">{g.playCount} / {targetPlays}회</span>
                {g.isCompleted ? (
                  <span className="text-emerald-400 font-bold flex items-center gap-0.5">
                    <CheckCircle2 className="w-3 h-3" /> 달성
                  </span>
                ) : (
                  <span className="text-purple-400 font-semibold">{g.progress}%</span>
                )}
              </div>
              <div className="w-full h-1.5 bg-slate-900 rounded-full overflow-hidden">
                <div
                  className={`h-full transition-all duration-300 ${
                    g.isCompleted ? 'bg-emerald-400' : 'bg-purple-500'
                  }`}
                  style={{ width: `${g.progress}%` }}
                />
              </div>
            </div>
          </div>
        ))}
      </div>
    </div>
  );
};

'use client';

import React, { useState } from 'react';
import { Swords, Trophy, Users, Shield, Award } from 'lucide-react';
import { Player, Play } from '@/types';
import { calculateAllPlayerStats } from '@/lib/stats-calculator';

interface PlayerHeadToHeadProps {
  players: Player[];
  plays: Play[];
}

export const PlayerHeadToHead: React.FC<PlayerHeadToHeadProps> = ({ players, plays }) => {
  const [player1Id, setPlayer1Id] = useState<string>(players[0]?.id || '');
  const [player2Id, setPlayer2Id] = useState<string>(players[1]?.id || '');

  const p1 = players.find(p => p.id === player1Id);
  const p2 = players.find(p => p.id === player2Id);

  // Calculate shared games stats
  let sharedPlaysCount = 0;
  let p1WinsInShared = 0;
  let p2WinsInShared = 0;
  const sharedGamesMap = new Map<string, { title: string; count: number; p1Wins: number; p2Wins: number }>();

  plays.forEach(play => {
    const ps1 = play.playerScores.find(p => p.playerId === player1Id);
    const ps2 = play.playerScores.find(p => p.playerId === player2Id);

    if (ps1 && ps2) {
      sharedPlaysCount += 1;
      if (ps1.winner) p1WinsInShared += 1;
      if (ps2.winner) p2WinsInShared += 1;

      let gStat = sharedGamesMap.get(play.gameId);
      if (!gStat) {
        gStat = { title: play.gameTitleKr || '게임', count: 0, p1Wins: 0, p2Wins: 0 };
        sharedGamesMap.set(play.gameId, gStat);
      }
      gStat.count += 1;
      if (ps1.winner) gStat.p1Wins += 1;
      if (ps2.winner) gStat.p2Wins += 1;
    }
  });

  const p1WinRate = sharedPlaysCount > 0 ? Math.round((p1WinsInShared / sharedPlaysCount) * 100) : 0;
  const p2WinRate = sharedPlaysCount > 0 ? Math.round((p2WinsInShared / sharedPlaysCount) * 100) : 0;

  // All players ranking table
  const allStats = calculateAllPlayerStats(players, plays);

  return (
    <div className="space-y-6">
      {/* 1. Head-to-Head Comparison Card */}
      <div className="p-5 rounded-2xl bg-slate-900/90 border border-slate-800 space-y-5">
        <div className="flex items-center gap-2">
          <div className="p-1.5 rounded-lg bg-rose-500/20 text-rose-400 border border-rose-500/30">
            <Swords className="w-4 h-4" />
          </div>
          <div>
            <h4 className="font-bold text-sm text-white">플레이어 1:1 맞대결 전적 분석 (Head-to-Head)</h4>
            <p className="text-xs text-slate-400">두 플레이어 간의 승률 및 대결 히스토리 비교</p>
          </div>
        </div>

        {/* Player Pickers */}
        <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
          <div className="p-3 bg-slate-800/60 border border-slate-700/60 rounded-xl space-y-1">
            <label className="text-[11px] text-slate-400 font-bold block">플레이어 1</label>
            <select
              value={player1Id}
              onChange={(e) => setPlayer1Id(e.target.value)}
              className="w-full bg-slate-900 border border-slate-700 rounded-lg px-3 py-1.5 text-xs text-white"
            >
              {players.map(p => (
                <option key={p.id} value={p.id}>{p.avatar} {p.name} {p.isUser ? '(나)' : ''}</option>
              ))}
            </select>
          </div>

          <div className="p-3 bg-slate-800/60 border border-slate-700/60 rounded-xl space-y-1">
            <label className="text-[11px] text-slate-400 font-bold block">플레이어 2</label>
            <select
              value={player2Id}
              onChange={(e) => setPlayer2Id(e.target.value)}
              className="w-full bg-slate-900 border border-slate-700 rounded-lg px-3 py-1.5 text-xs text-white"
            >
              {players.map(p => (
                <option key={p.id} value={p.id}>{p.avatar} {p.name} {p.isUser ? '(나)' : ''}</option>
              ))}
            </select>
          </div>
        </div>

        {/* VS Metric Visualizer */}
        {p1 && p2 && (
          <div className="p-4 bg-slate-950/60 border border-slate-800 rounded-2xl space-y-4">
            <div className="flex items-center justify-between">
              {/* Player 1 Card */}
              <div className="flex items-center gap-3">
                <span className="text-3xl">{p1.avatar || '🎲'}</span>
                <div>
                  <span className="font-extrabold text-sm text-white block">{p1.name}</span>
                  <span className="text-xs text-indigo-400 font-black">{p1WinsInShared}승 ({p1WinRate}%)</span>
                </div>
              </div>

              {/* VS Badge */}
              <div className="px-3 py-1 rounded-full bg-rose-500/20 text-rose-400 border border-rose-500/30 text-xs font-black">
                {sharedPlaysCount}회 맞대결
              </div>

              {/* Player 2 Card */}
              <div className="flex items-center gap-3 text-right flex-row-reverse">
                <span className="text-3xl">{p2.avatar || '🎲'}</span>
                <div>
                  <span className="font-extrabold text-sm text-white block">{p2.name}</span>
                  <span className="text-xs text-sky-400 font-black">{p2WinsInShared}승 ({p2WinRate}%)</span>
                </div>
              </div>
            </div>

            {/* Split Bar */}
            <div className="w-full h-3 bg-slate-800 rounded-full overflow-hidden flex">
              <div
                className="h-full bg-indigo-500 transition-all duration-500"
                style={{ width: `${sharedPlaysCount > 0 ? (p1WinsInShared / sharedPlaysCount) * 100 : 50}%` }}
              />
              <div
                className="h-full bg-sky-500 transition-all duration-500"
                style={{ width: `${sharedPlaysCount > 0 ? (p2WinsInShared / sharedPlaysCount) * 100 : 50}%` }}
              />
            </div>

            {/* Shared Games Breakdown */}
            {sharedGamesMap.size > 0 && (
              <div className="pt-2 space-y-1.5 border-t border-slate-800">
                <span className="text-[11px] text-slate-400 font-bold uppercase block">게임별 맞대결 승패</span>
                <div className="grid grid-cols-1 sm:grid-cols-2 gap-2">
                  {Array.from(sharedGamesMap.entries()).map(([gId, stat]) => (
                    <div key={gId} className="flex items-center justify-between p-2 rounded-lg bg-slate-900 border border-slate-800 text-xs">
                      <span className="text-slate-300 font-medium truncate max-w-[140px]">{stat.title}</span>
                      <span className="text-slate-400 font-mono">
                        <strong className="text-indigo-400">{stat.p1Wins}승</strong> : <strong className="text-sky-400">{stat.p2Wins}승</strong> ({stat.count}전)
                      </span>
                    </div>
                  ))}
                </div>
              </div>
            )}
          </div>
        )}
      </div>

      {/* 2. All Players Leaderboard */}
      <div className="p-5 rounded-2xl bg-slate-900/90 border border-slate-800 space-y-4">
        <div className="flex items-center gap-2">
          <div className="p-1.5 rounded-lg bg-amber-500/20 text-amber-400 border border-amber-500/30">
            <Trophy className="w-4 h-4" />
          </div>
          <div>
            <h4 className="font-bold text-sm text-white">플레이어 랭킹 및 전체 승률</h4>
            <p className="text-xs text-slate-400">모임 멤버별 승률 및 나와의 상대 전적</p>
          </div>
        </div>

        <div className="space-y-2">
          {allStats.map((stat, idx) => (
            <div
              key={stat.player.id}
              className="flex items-center justify-between p-3 rounded-xl bg-slate-800/60 border border-slate-700/60 text-xs"
            >
              <div className="flex items-center gap-3">
                <span className="text-slate-500 font-bold w-4">#{idx + 1}</span>
                <span className="text-lg">{stat.player.avatar || '🎲'}</span>
                <div>
                  <span className="font-bold text-white block">
                    {stat.player.name} {stat.player.isUser ? '(나)' : ''}
                  </span>
                  {stat.player.notes && <span className="text-[10px] text-slate-400">{stat.player.notes}</span>}
                </div>
              </div>

              <div className="flex items-center gap-4 text-right">
                <div>
                  <span className="text-[10px] text-slate-400 block">총 전적</span>
                  <span className="font-bold text-slate-200">{stat.totalPlays}전 {stat.totalWins}승</span>
                </div>
                <div>
                  <span className="text-[10px] text-slate-400 block">전체 승률</span>
                  <span className="font-black text-amber-400">{stat.winRate}%</span>
                </div>
              </div>
            </div>
          ))}
        </div>
      </div>
    </div>
  );
};

'use client';

import React from 'react';
import { Coins, TrendingDown, AlertCircle, Sparkles } from 'lucide-react';
import { Game, Play } from '@/types';
import { calculateGameStatsMap } from '@/lib/stats-calculator';

interface CostPerPlayLeaderboardProps {
  games: Game[];
  plays: Play[];
}

export const CostPerPlayLeaderboard: React.FC<CostPerPlayLeaderboardProps> = ({ games, plays }) => {
  const gameStats = calculateGameStatsMap(games, plays);

  // Filter games that have purchase price recorded
  const gamesWithPrice = Array.from(gameStats.values())
    .filter(g => g.purchasePrice && g.purchasePrice > 0);

  // Top Value (Lowest cost per play)
  const bestValueGames = [...gamesWithPrice]
    .filter(g => g.playCount > 0)
    .sort((a, b) => (a.costPerPlay || 0) - (b.costPerPlay || 0))
    .slice(0, 5);

  // High cost per play / Underplayed
  const highCostGames = [...gamesWithPrice]
    .sort((a, b) => (b.costPerPlay || 0) - (a.costPerPlay || 0))
    .slice(0, 5);

  return (
    <div className="p-5 rounded-2xl bg-slate-900/90 border border-slate-800 space-y-4">
      <div className="flex items-center gap-2">
        <div className="p-1.5 rounded-lg bg-amber-500/20 text-amber-400 border border-amber-500/30">
          <Coins className="w-4 h-4" />
        </div>
        <div>
          <h4 className="font-bold text-sm text-white">플레이당 비용 분석 (Cost Per Play / 가성비)</h4>
          <p className="text-xs text-slate-400">구매가 대비 플레이 횟수 기반 가성비 랭킹 (구매가 / 플레이수)</p>
        </div>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-2 gap-4">

        {/* 1. Best Value Games (가장 뽕 뽑은 게임 TOP) */}
        <div className="p-4 rounded-xl bg-slate-800/60 border border-emerald-500/30 space-y-3">
          <div className="flex items-center gap-1.5 text-xs font-bold text-emerald-400">
            <Sparkles className="w-4 h-4" />
            <span>최고의 가성비 게임 (가장 뽕 뽑음!)</span>
          </div>

          <div className="space-y-2">
            {bestValueGames.map((g, idx) => (
              <div key={g.gameId} className="flex items-center justify-between p-2 rounded-lg bg-slate-900/80 text-xs">
                <div className="flex items-center gap-2">
                  <span className="font-bold text-emerald-400 w-3.5">#{idx + 1}</span>
                  <span className="font-semibold text-white truncate max-w-[120px]">{g.gameTitleKr}</span>
                  <span className="text-[10px] text-slate-400">({g.playCount}회)</span>
                </div>
                <div className="text-right font-mono">
                  <span className="text-emerald-300 font-bold">{g.costPerPlay?.toLocaleString()}원</span>
                  <span className="text-[10px] text-slate-400 block">{g.purchasePrice?.toLocaleString()}원 구매</span>
                </div>
              </div>
            ))}
          </div>
        </div>

        {/* 2. Need More Plays (더 돌려야 할 게임) */}
        <div className="p-4 rounded-xl bg-slate-800/60 border border-amber-500/30 space-y-3">
          <div className="flex items-center gap-1.5 text-xs font-bold text-amber-400">
            <AlertCircle className="w-4 h-4" />
            <span>더 많이 플레이해야 할 게임 (회당 비용 높음)</span>
          </div>

          <div className="space-y-2">
            {highCostGames.map((g, idx) => (
              <div key={g.gameId} className="flex items-center justify-between p-2 rounded-lg bg-slate-900/80 text-xs">
                <div className="flex items-center gap-2">
                  <span className="font-bold text-amber-400 w-3.5">#{idx + 1}</span>
                  <span className="font-semibold text-white truncate max-w-[120px]">{g.gameTitleKr}</span>
                  <span className="text-[10px] text-slate-400">({g.playCount}회)</span>
                </div>
                <div className="text-right font-mono">
                  <span className="text-amber-300 font-bold">{g.costPerPlay?.toLocaleString()}원</span>
                  <span className="text-[10px] text-slate-400 block">{g.purchasePrice?.toLocaleString()}원 구매</span>
                </div>
              </div>
            ))}
          </div>
        </div>

      </div>
    </div>
  );
};

