'use client';

import React, { useState, useEffect, useRef } from 'react';
import confetti from 'canvas-confetti';
import { Sparkles, Crown, RotateCcw, Users, Play } from 'lucide-react';
import { Player } from '@/types';

interface TouchPoint {
  id: number;
  x: number;
  y: number;
  color: string;
}

const COLORS = [
  '#ef4444', '#3b82f6', '#10b981', '#f59e0b', 
  '#8b5cf6', '#ec4899', '#06b6d4', '#84cc16'
];

interface StartPlayerChooserProps {
  players?: Player[];
}

export const StartPlayerChooser: React.FC<StartPlayerChooserProps> = ({ players = [] }) => {
  const [mode, setMode] = useState<'touch' | 'list'>('touch');
  const [touches, setTouches] = useState<TouchPoint[]>([]);
  const [winnerTouchId, setWinnerTouchId] = useState<number | null>(null);
  const [countdown, setCountdown] = useState<number | null>(null);
  const containerRef = useRef<HTMLDivElement>(null);
  const timerRef = useRef<any>(null);

  // List mode state
  const [selectedPlayerNames, setSelectedPlayerNames] = useState<string[]>(
    players.map(p => p.name)
  );
  const [listWinner, setListWinner] = useState<string | null>(null);
  const [isSpinning, setIsSpinning] = useState(false);

  // Handle Touch Screen interactions (Chwazi-style)
  const handleTouchStart = (e: React.TouchEvent) => {
    if (winnerTouchId !== null) return;
    if (!containerRef.current) return;
    const rect = containerRef.current.getBoundingClientRect();

    const newTouches: TouchPoint[] = [];
    for (let i = 0; i < e.touches.length; i++) {
      const t = e.touches[i];
      newTouches.push({
        id: t.identifier,
        x: t.clientX - rect.left,
        y: t.clientY - rect.top,
        color: COLORS[i % COLORS.length],
      });
    }
    setTouches(newTouches);

    // If at least 2 fingers, start 3s countdown
    if (newTouches.length >= 2) {
      if (timerRef.current) clearTimeout(timerRef.current);
      setCountdown(3);
    }
  };

  const handleTouchEnd = (e: React.TouchEvent) => {
    if (winnerTouchId !== null) return;
    if (e.touches.length < 2) {
      setCountdown(null);
      if (timerRef.current) clearTimeout(timerRef.current);
    }

    if (!containerRef.current) return;
    const rect = containerRef.current.getBoundingClientRect();
    const activeTouches: TouchPoint[] = [];
    for (let i = 0; i < e.touches.length; i++) {
      const t = e.touches[i];
      activeTouches.push({
        id: t.identifier,
        x: t.clientX - rect.left,
        y: t.clientY - rect.top,
        color: COLORS[i % COLORS.length],
      });
    }
    setTouches(activeTouches);
  };

  // Countdown timer effect
  useEffect(() => {
    if (countdown === null) return;

    if (countdown > 0) {
      const timer = setTimeout(() => {
        setCountdown(countdown - 1);
      }, 800);
      return () => clearTimeout(timer);
    } else if (countdown === 0 && touches.length >= 2) {
      // Pick random winner finger!
      const randIdx = Math.floor(Math.random() * touches.length);
      const chosen = touches[randIdx];
      setWinnerTouchId(chosen.id);

      try {
        confetti({
          particleCount: 70,
          spread: 60,
          origin: {
            x: chosen.x / (containerRef.current?.clientWidth || window.innerWidth),
            y: chosen.y / (containerRef.current?.clientHeight || window.innerHeight),
          },
        });
      } catch (e) {}
    }
  }, [countdown, touches]);

  const resetTouch = () => {
    setWinnerTouchId(null);
    setTouches([]);
    setCountdown(null);
    if (timerRef.current) clearTimeout(timerRef.current);
  };

  // List mode spin picker
  const handleSpinList = () => {
    if (selectedPlayerNames.length < 2 || isSpinning) return;
    setIsSpinning(true);
    setListWinner(null);

    let counter = 0;
    const interval = setInterval(() => {
      const randomName = selectedPlayerNames[Math.floor(Math.random() * selectedPlayerNames.length)];
      setListWinner(randomName);
      counter++;
      if (counter > 25) {
        clearInterval(interval);
        setIsSpinning(false);
        try {
          confetti({ particleCount: 80, spread: 70, origin: { y: 0.6 } });
        } catch (e) {}
      }
    }, 80);
  };

  return (
    <div className="p-5 rounded-2xl bg-slate-900/90 border border-slate-800 space-y-4">
      {/* Header & Mode Switch */}
      <div className="flex items-center justify-between">
        <div className="flex items-center gap-2">
          <div className="p-1.5 rounded-lg bg-amber-500/20 text-amber-400 border border-amber-500/30">
            <Crown className="w-4 h-4" />
          </div>
          <div>
            <h4 className="font-bold text-sm text-white">시작 플레이어 뽑기 (선뽑기)</h4>
            <p className="text-xs text-slate-400">화면에 손가락을 대거나 룰렛으로 선 플레이어 선정</p>
          </div>
        </div>

        <div className="flex items-center gap-1 bg-slate-800 p-1 rounded-xl">
          <button
            onClick={() => { setMode('touch'); resetTouch(); }}
            className={`px-3 py-1 rounded-lg text-xs font-bold transition-colors ${
              mode === 'touch' ? 'bg-indigo-600 text-white' : 'text-slate-400 hover:text-white'
            }`}
          >
            👆 멀티터치 방식
          </button>
          <button
            onClick={() => setMode('list')}
            className={`px-3 py-1 rounded-lg text-xs font-bold transition-colors ${
              mode === 'list' ? 'bg-indigo-600 text-white' : 'text-slate-400 hover:text-white'
            }`}
          >
            📋 멤버 룰렛 방식
          </button>
        </div>
      </div>

      {mode === 'touch' ? (
        /* Multi-touch Screen Area */
        <div className="space-y-2">
          <div
            ref={containerRef}
            onTouchStart={handleTouchStart}
            onTouchEnd={handleTouchEnd}
            onTouchCancel={handleTouchEnd}
            className="w-full h-72 bg-slate-950 rounded-2xl border-2 border-dashed border-indigo-500/30 relative flex flex-col items-center justify-center overflow-hidden cursor-pointer select-none touch-none"
          >
            {/* Background Hint / Countdown */}
            {countdown !== null && countdown > 0 && (
              <div className="absolute text-7xl font-black text-amber-400 animate-ping">
                {countdown}
              </div>
            )}

            {touches.length === 0 && (
              <div className="text-center p-4 pointer-events-none space-y-2">
                <span className="text-4xl block animate-bounce">👆</span>
                <p className="text-sm font-bold text-slate-300">화면에 각자의 손가락을 올려놓으세요!</p>
                <p className="text-xs text-slate-500">2명 이상 손가락을 대면 카운트다운 후 선 플레이어가 지목됩니다.</p>
              </div>
            )}

            {/* Render Touching Circles */}
            {touches.map((t) => {
              const isWinner = winnerTouchId === t.id;
              return (
                <div
                  key={t.id}
                  style={{
                    left: `${t.x - 36}px`,
                    top: `${t.y - 36}px`,
                    backgroundColor: t.color,
                  }}
                  className={`absolute w-20 h-20 rounded-full flex items-center justify-center text-white font-black text-xl shadow-2xl transition-transform ${
                    isWinner
                      ? 'scale-125 ring-8 ring-amber-400 z-30 animate-pulse'
                      : winnerTouchId !== null
                      ? 'opacity-20 scale-75'
                      : 'animate-pulse'
                  }`}
                >
                  {isWinner ? '👑 선!' : '🎲'}
                </div>
              );
            })}
          </div>

          <div className="flex justify-between items-center text-xs text-slate-400">
            <span>감지된 손가락: <strong>{touches.length}개</strong></span>
            {winnerTouchId !== null && (
              <button
                onClick={resetTouch}
                className="px-3 py-1 bg-indigo-600 text-white rounded-lg font-bold flex items-center gap-1"
              >
                <RotateCcw className="w-3.5 h-3.5" />
                <span>다시 뽑기</span>
              </button>
            )}
          </div>
        </div>
      ) : (
        /* Member List Roulette Mode */
        <div className="p-4 bg-slate-950/60 rounded-2xl border border-slate-800 space-y-4">
          <div className="flex items-center justify-between">
            <span className="text-xs text-slate-400 font-bold">참여 멤버 선택</span>
            <span className="text-xs text-indigo-400">{selectedPlayerNames.length}명 참여 중</span>
          </div>

          {/* Member tags */}
          <div className="flex flex-wrap gap-2">
            {players.map((p) => {
              const isSelected = selectedPlayerNames.includes(p.name);
              return (
                <button
                  key={p.id}
                  onClick={() => {
                    if (isSelected) {
                      setSelectedPlayerNames(selectedPlayerNames.filter(n => n !== p.name));
                    } else {
                      setSelectedPlayerNames([...selectedPlayerNames, p.name]);
                    }
                  }}
                  className={`px-3 py-1.5 rounded-xl text-xs font-bold transition-all ${
                    isSelected
                      ? 'bg-indigo-600 text-white shadow-md'
                      : 'bg-slate-800 text-slate-400 border border-slate-700'
                  }`}
                >
                  {p.avatar} {p.name}
                </button>
              );
            })}
          </div>

          {/* Winner Display */}
          <div className="h-28 rounded-2xl bg-slate-900 border border-slate-800 flex items-center justify-center text-center p-4">
            {listWinner ? (
              <div className="space-y-1 animate-in zoom-in-95">
                <span className="text-xs text-amber-400 font-bold flex items-center justify-center gap-1">
                  <Crown className="w-4 h-4" /> 시작 플레이어 당첨!
                </span>
                <span className="text-2xl font-black text-white block">{listWinner}</span>
              </div>
            ) : (
              <p className="text-xs text-slate-500">아래 버튼을 눌러 선 플레이어를 추첨하세요.</p>
            )}
          </div>

          <button
            onClick={handleSpinList}
            disabled={selectedPlayerNames.length < 2 || isSpinning}
            className="w-full py-3 rounded-xl bg-gradient-to-r from-amber-500 to-amber-600 hover:from-amber-400 hover:to-amber-500 text-slate-950 font-black text-sm shadow-lg shadow-amber-500/20 disabled:opacity-50 flex items-center justify-center gap-2 transition-all active:scale-95"
          >
            <Sparkles className="w-4 h-4" />
            <span>{isSpinning ? '추첨 중...' : '선 플레이어 룰렛 돌리기!'}</span>
          </button>
        </div>
      )}
    </div>
  );
};

'use client';

import React, { useState } from 'react';
import confetti from 'canvas-confetti';
import { Sparkles, Dices, Users, Clock, Flame, RotateCcw } from 'lucide-react';
import { Game } from '@/types';
import { GameCard } from '@/components/collection/GameCard';

interface GamePickerModalProps {
  games: Game[];
}

export const GamePickerModal: React.FC<GamePickerModalProps> = ({ games }) => {
  const [playerCount, setPlayerCount] = useState<number>(3);
  const [maxTime, setMaxTime] = useState<number>(90);
  const [weightFilter, setWeightFilter] = useState<'all' | 'light' | 'medium' | 'heavy'>('all');
  const [pickedGame, setPickedGame] = useState<Game | null>(null);
  const [isPicking, setIsPicking] = useState(false);

  // Filter available games
  const eligibleGames = games.filter(g => {
    if (g.status !== 'owned') return false;
    if (g.minPlayers > playerCount || g.maxPlayers < playerCount) return false;
    if (g.maxPlaytime > maxTime) return false;

    if (weightFilter === 'light' && (g.weight || 0) >= 2.5) return false;
    if (weightFilter === 'medium' && ((g.weight || 0) < 2.5 || (g.weight || 0) >= 3.5)) return false;
    if (weightFilter === 'heavy' && (g.weight || 0) < 3.5) return false;

    return true;
  });

  const handlePickRandomGame = () => {
    if (eligibleGames.length === 0 || isPicking) return;
    setIsPicking(true);
    setPickedGame(null);

    let count = 0;
    const interval = setInterval(() => {
      const randGame = eligibleGames[Math.floor(Math.random() * eligibleGames.length)];
      setPickedGame(randGame);
      count++;
      if (count > 20) {
        clearInterval(interval);
        setIsPicking(false);
        try {
          confetti({ particleCount: 80, spread: 70, origin: { y: 0.6 } });
        } catch (e) {}
      }
    }, 90);
  };

  return (
    <div className="p-5 rounded-2xl bg-slate-900/90 border border-slate-800 space-y-5">
      <div className="flex items-center gap-2">
        <div className="p-1.5 rounded-lg bg-indigo-500/20 text-indigo-400 border border-indigo-500/30">
          <Dices className="w-4 h-4" />
        </div>
        <div>
          <h4 className="font-bold text-sm text-white">오늘 뭐 하지? (스마트 게임 추천기)</h4>
          <p className="text-xs text-slate-400">인원수, 플레이 타임, 난이도 조건에 맞는 게임을 내 컬렉션에서 추천</p>
        </div>
      </div>

      {/* Filter Parameters */}
      <div className="grid grid-cols-1 sm:grid-cols-3 gap-3 p-4 bg-slate-950/60 rounded-xl border border-slate-800">
        <div>
          <label className="text-xs text-slate-400 font-bold block mb-1">
            참여 인원 ({playerCount}인)
          </label>
          <input
            type="range"
            min="1"
            max="8"
            value={playerCount}
            onChange={(e) => setPlayerCount(Number(e.target.value))}
            className="w-full accent-indigo-500"
          />
        </div>

        <div>
          <label className="text-xs text-slate-400 font-bold block mb-1">
            최대 허용 시간 ({maxTime}분 이내)
          </label>
          <input
            type="range"
            min="15"
            max="240"
            step="15"
            value={maxTime}
            onChange={(e) => setMaxTime(Number(e.target.value))}
            className="w-full accent-sky-500"
          />
        </div>

        <div>
          <label className="text-xs text-slate-400 font-bold block mb-1">
            난이도 선택
          </label>
          <select
            value={weightFilter}
            onChange={(e) => setWeightFilter(e.target.value as any)}
            className="w-full bg-slate-900 border border-slate-700 rounded-lg px-2.5 py-1.5 text-xs text-white"
          >
            <option value="all">전체 난이도 무관</option>
            <option value="light">입문/파티 (Weight 2.5 미만)</option>
            <option value="medium">중급 전략 (Weight 2.5 ~ 3.5)</option>
            <option value="heavy">헤비 전략 (Weight 3.5 이상)</option>
          </select>
        </div>
      </div>

      {/* Matching Count & Action Button */}
      <div className="flex flex-col sm:flex-row items-center justify-between gap-3">
        <span className="text-xs text-slate-400">
          조건에 일치하는 보유 게임: <strong className="text-indigo-400">{eligibleGames.length}개</strong>
        </span>
        <button
          onClick={handlePickRandomGame}
          disabled={eligibleGames.length === 0 || isPicking}
          className="w-full sm:w-auto px-6 py-2.5 rounded-xl bg-gradient-to-r from-indigo-600 to-indigo-500 hover:from-indigo-500 hover:to-indigo-400 text-white font-bold text-sm shadow-lg shadow-indigo-600/30 flex items-center justify-center gap-2 active:scale-95 transition-all disabled:opacity-50"
        >
          <Sparkles className="w-4 h-4" />
          <span>{isPicking ? '추천 게임 선정 중...' : '오늘의 게임 추천받기!'}</span>
        </button>
      </div>

      {/* Picked Game Card Display */}
      {pickedGame && (
        <div className="p-4 bg-indigo-950/20 border border-indigo-500/40 rounded-2xl space-y-2 animate-in zoom-in-95">
          <span className="text-xs text-amber-400 font-black uppercase tracking-wider flex items-center gap-1">
            🎉 오늘의 추천 게임 결정!
          </span>
          <div className="max-w-xs mx-auto">
            <GameCard game={pickedGame} />
          </div>
        </div>
      )}
    </div>
  );
};

'use client';

import React, { useState } from 'react';
import { ShieldCheck, ShoppingBag, Copy, Check } from 'lucide-react';
import { Game } from '@/types';

interface SleeveShoppingCalculatorProps {
  games: Game[];
}

export const SleeveShoppingCalculator: React.FC<SleeveShoppingCalculatorProps> = ({ games }) => {
  const [copied, setCopied] = useState(false);

  // Group sleeves by size for games that don't have sleeves equipped
  const neededSleevesMap = new Map<string, { totalCount: number; gamesList: string[] }>();

  games.forEach(g => {
    if (g.status === 'owned' && g.sleeves) {
      g.sleeves.forEach(slv => {
        if (!slv.hasSleeves) {
          const current = neededSleevesMap.get(slv.size) || { totalCount: 0, gamesList: [] };
          current.totalCount += slv.count;
          if (!current.gamesList.includes(g.titleKr)) {
            current.gamesList.push(g.titleKr);
          }
          neededSleevesMap.set(slv.size, current);
        }
      });
    }
  });

  const sleeveItems = Array.from(neededSleevesMap.entries()).map(([size, val]) => ({
    size,
    totalCount: val.totalCount,
    packsNeeded: Math.ceil(val.totalCount / 100), // 100 per pack standard
    gamesList: val.gamesList,
  }));

  const handleCopyShoppingList = () => {
    if (sleeveItems.length === 0) return;
    const text = sleeveItems
      .map(item => `• [${item.size}] ${item.totalCount}장 (약 ${item.packsNeeded}팩) - 대상: ${item.gamesList.join(', ')}`)
      .join('\n');

    navigator.clipboard.writeText(`[보드게임 슬리브 쇼핑 리스트]\n${text}`);
    setCopied(true);
    setTimeout(() => setCopied(false), 2000);
  };

  return (
    <div className="p-5 rounded-2xl bg-slate-900/90 border border-slate-800 space-y-4">
      <div className="flex items-center justify-between">
        <div className="flex items-center gap-2">
          <div className="p-1.5 rounded-lg bg-sky-500/20 text-sky-400 border border-sky-500/30">
            <ShieldCheck className="w-4 h-4" />
          </div>
          <div>
