        winner: ps.winner || false,
        startPlayer: ps.startPlayer || false,
        role: ps.role || undefined,
        newPlayer: ps.newPlayer || false,
      };
    });

    return {
      id: `play-${p.uuid || p.id || Math.random().toString()}`,
